const compact = (r) => ({ totalIncome: r.totalIncome, taxBeforeRebatePaise: r.taxBeforeRebate, rebatePaise: r.rebate, taxAfterRebatePaise: r.taxAfterRebate, final: r.finalTax });

describe("independent Python reference: every case agrees", () => {
  test(`${GOLDEN.length} cases (slab edges, the rebate band, caps, HRA, NPS, ceiling, break-even)`, () => {
    let compared = 0;
    for (const g of GOLDEN) {
      const r = calculate(g.input);
      const label = JSON.stringify(g.input);
      if (g.status === "unsupported") {
        assert.equal(r.status, "unsupported", label);
        continue;
      }
      assert.equal(r.status, "ok", label);
      assert.deepEqual(compact(r.old), g.old, `old ${label}`);
      assert.deepEqual(compact(r.new), g.new, `new ${label}`);
      assert.equal(r.comparison.lower, g.lower, label);
      assert.equal(r.comparison.differenceRupees, g.difference, label);
      assert.equal(r.breakEven.status, g.breakEven.status, label);
      if (g.breakEven.status === "found") {
        assert.equal(r.breakEven.extraRupees, g.breakEven.extraRupees, `extra ${label}`);
        assert.equal(r.breakEven.currentRupees, g.breakEven.currentRupees, `current ${label}`);
        assert.equal(r.breakEven.requiredRupees, g.breakEven.requiredRupees, `required ${label}`);
        assert.equal(r.breakEven.requiredApproxRupees, g.breakEven.requiredApproxRupees, `approx ${label}`);
      }
      compared++;
    }
    assert.ok(compared > 200);
  });
});

describe("section 516 rounding: a dedicated helper, not Math.round", () => {
  const cases = [
    [0, 0], [10, 10], [100, 100], [123_450, 123_450],       // an exact multiple of 10
    [1, 0], [2, 0], [3, 0], [4, 0], [123_454, 123_450],      // last figure 1 to 4 goes down
    [5, 10], [15, 20], [123_455, 123_460], [1_199_995, 1_200_000],   // last figure 5 goes up
    [6, 10], [7, 10], [8, 10], [9, 10], [123_459, 123_460],  // 6 to 9 goes up
    [999_999_999, 1_000_000_000], [5_000_004, 5_000_000], [5_000_005, 5_000_010],  // large values
  ];
  for (const [rupees, expected] of cases) {
    test(`Rs ${rupees} rounds to Rs ${expected}`, () => assert.equal(roundStatutory(rupees * 100), expected));
  }

  test("paise are ignored before rounding: 4.99 is 4 (down), 5.00 is 5 (up), 4.99 + 0.01 is not", () => {
    assert.equal(roundStatutory(499), 0);          // Rs 4.99 -> Rs 4 -> 0
    assert.equal(roundStatutory(500), 10);         // Rs 5.00 -> 10
    assert.equal(roundStatutory(1_299_99), 1_300 - 0);   // Rs 1299.99 -> 1299 -> 1300 (last figure 9)
    assert.equal(roundStatutory(1_204_99), 1_200);  // Rs 1204.99 -> 1204 -> 1200
  });

  test("Math.round would be wrong: 12.5 rupees of cess is not rounded to 13 before the ten", () => {
    // tax after rebate Rs 10,000.00 + 4% cess = Rs 10,400.00 -> 10,400; a tax of Rs 5,000.50 + cess 200.02 = 5,200.52 -> 5,200 -> 5,200
    const r = calculate({ salary: 400_010 + 75_000 });   // total income 4,00,010 -> 5% of 10 = Rs 0.50 tax, fully rebated
    assert.equal(r.new.taxBeforeRebate, 50);              // 50 paise
    assert.equal(r.new.finalTax, 0);
  });
});

describe("hand-worked cases (derivations in the comments)", () => {
  test("Rs 15,00,000 salary, no deductions", () => {
    // NEW: 15,00,000 - 75,000 = 14,25,000. Tax: 4L-8L 5% = 20,000; 8L-12L 10% = 40,000; 12L-14.25L 15% of 2,25,000 = 33,750 -> 93,750.
    //      Rebate: income is above 12L; excess over 12L = 2,25,000 > tax 93,750 -> no rebate. Cess 4% = 3,750 -> 97,500.
    // OLD: 15,00,000 - 50,000 = 14,50,000. Tax: 12,500 + 20% of 5,00,000 = 1,12,500 at 10L; + 30% of 4,50,000 = 1,35,000 -> 2,47,500. Cess 9,900 -> 2,57,400.
    const r = calculate({ salary: 1_500_000 });
    assert.equal(r.new.totalIncome, 1_425_000);
    assert.equal(r.new.finalTax, 97_500);
    assert.equal(r.old.totalIncome, 1_450_000);
    assert.equal(r.old.finalTax, 257_400);
    assert.equal(r.comparison.lower, "new");
    assert.equal(r.comparison.differenceRupees, 159_900);
  });

  test("the new-regime rebate: total income exactly Rs 12,00,000 pays nothing; Rs 10 more pays Rs 10; the relief ends where the tax equals the excess", () => {
    // 12,00,000: tax 20,000 + 40,000 = 60,000, rebate min(60,000, 60,000) = 60,000 -> 0.
    assert.equal(calculate({ salary: 1_275_000 }).new.finalTax, 0);
    // 12,00,010: tax 60,001.50; excess 10 -> tax after relief = 10.00 -> cess 0.40 -> 10.40 -> Rs 10.
    const r = calculate({ salary: 1_275_010 });
    assert.equal(r.new.totalIncome, 1_200_010);
    assert.equal(r.new.taxBeforeRebate, 6_000_150);
    assert.equal(r.new.rebate, 5_999_150);
    assert.equal(r.new.taxAfterRebate, 1_000);
    assert.equal(r.new.finalTax, 10);
    // 12,10,000: tax 60,000 + 15% of 10,000 = 61,500; excess 10,000 -> 10,000; cess 400 -> 10,400.
    assert.equal(calculate({ salary: 1_285_000 }).new.finalTax, 10_400);
    // 12,75,000: tax 60,000 + 11,250 = 71,250; excess 75,000 > 71,250 -> no relief; cess 2,850 -> 74,100.
    const edge = calculate({ salary: 1_350_000 });
    assert.equal(edge.new.totalIncome, 1_275_000);
    assert.equal(edge.new.rebate, 0);
    assert.equal(edge.new.finalTax, 74_100);
  });

  test("the old-regime rebate is a cliff: Rs 5,00,000 pays nothing, Rs 5,00,010 pays Rs 13,000", () => {
    // 5,00,000: tax 12,500 = rebate -> 0. 5,00,010: 12,500 + 20% of 10 = 12,502; no rebate; cess 500.08 -> 13,002.08 -> 13,000.
    assert.equal(calculate({ salary: 550_000 }).old.finalTax, 0);
    assert.equal(calculate({ salary: 550_010 }).old.finalTax, 13_000);
  });

  test("a salary of Rs 12,75,000 or less pays nothing in the new regime; Rs 12,75,010 pays Rs 10", () => {
    assert.equal(calculate({ salary: 1_275_000 }).new.finalTax, 0);
    assert.equal(calculate({ salary: 1_275_010 }).new.finalTax, 10);
  });

  test("HRA, the three amounts in turn (rule 279)", () => {
    const h = (o) => hraExemptionPaise({ ...DEFAULT_INPUT, ...o }) / 100;
    assert.equal(h({ basicPlusDa: 600_000, hraReceived: 100_000, rentPaid: 400_000, highCity: true }), 100_000);   // received: 1,00,000 < 3,40,000 and 3,00,000
    assert.equal(h({ basicPlusDa: 600_000, hraReceived: 300_000, rentPaid: 150_000, highCity: true }), 90_000);    // rent - 10% of 6,00,000 = 90,000
    assert.equal(h({ basicPlusDa: 600_000, hraReceived: 400_000, rentPaid: 500_000, highCity: true }), 300_000);   // 50% of 6,00,000
    assert.equal(h({ basicPlusDa: 600_000, hraReceived: 400_000, rentPaid: 500_000, highCity: false }), 240_000);  // 40% of 6,00,000
    assert.equal(h({ basicPlusDa: 600_000, hraReceived: 300_000, rentPaid: 60_000 }), 0);                          // rent is 10% of salary: nothing above it
    assert.equal(h({ basicPlusDa: 355_555, hraReceived: 200_000, rentPaid: 100_000, highCity: true }), 64_444.5);  // 1,00,000 - 35,555.5
  });

  test("deduction caps: entered and used are both reported", () => {
    const r = calculate({ salary: 1_800_000, section80C: 200_000, ownNps: 70_000, healthSelfFamily: 40_000, healthParents: 60_000, parentsSenior: false, homeLoanInterest: 250_000 });
    assert.equal(r.old.lines.section80C.entered, 20_000_000);
    assert.equal(r.old.lines.section80C.used, 15_000_000);
    assert.equal(r.old.lines.ownNps.used, 5_000_000);
    assert.equal(r.old.lines.healthSelfFamily.used, 2_500_000);
    assert.equal(r.old.lines.healthParents.used, 2_500_000);
    assert.equal(r.old.houseLoss.used, 20_000_000);
    assert.equal(calculate({ salary: 1_800_000, healthParents: 60_000, parentsSenior: true }).old.lines.healthParents.used, 5_000_000);
    assert.equal(calculate({ salary: 1_800_000, homeLoanInterest: 250_000, homeLoanOtherPurpose: true }).old.houseLoss.used, 3_000_000);
  });

  test("the new regime ignores every old-regime deduction (but keeps the employer's NPS at 14%)", () => {
    const base = calculate({ salary: 2_000_000 });
    const loaded = calculate({ salary: 2_000_000, section80C: 150_000, ownNps: 50_000, healthSelfFamily: 25_000, homeLoanInterest: 200_000, professionalTax: 2_400, otherDeductions: 500_000, basicPlusDa: 800_000, hraReceived: 300_000, rentPaid: 600_000 });
    assert.deepEqual(compact(loaded.new), compact(base.new));
    const nps = calculate({ salary: 2_000_000, basicPlusDa: 1_000_000, employerNps: 200_000 });
    assert.equal(nps.new.lines.employerNps.used, 14_000_000);   // 14% of 10,00,000 = 1,40,000
    assert.equal(nps.old.lines.employerNps.used, 10_000_000);   // 10% in the old regime
    assert.equal(calculate({ salary: 2_000_000, basicPlusDa: 1_000_000, employerNps: 200_000, employerGovernment: true }).old.lines.employerNps.used, 14_000_000);
  });

  test("the Chapter VIII deductions cannot take the income below zero (s.122(2))", () => {
    const r = calculate({ salary: 300_000, section80C: 150_000, otherDeductions: 900_000 });
    assert.equal(r.old.totalIncome, 0);
    assert.equal(r.old.finalTax, 0);
  });
});

describe("the supported income ceiling", () => {
  test("exactly Rs 50,00,000 is calculated; one rupee more is refused, not approximated", () => {
    assert.equal(calculate({ salary: 5_000_000 }).status, "ok");
    assert.equal(calculate({ salary: 4_999_999, otherIncome: 1 }).status, "ok");
    const over = calculate({ salary: 5_000_001 });
    assert.equal(over.status, "unsupported");
    assert.equal(over.reason, "income-above-ceiling");
    assert.equal(over.ceiling, 5_000_000);
    assert.equal(calculate({ salary: 3_000_000, otherIncome: 2_000_001 }).status, "unsupported");
    assert.ok(isWithinSupportedIncome({ salary: 5_000_000, otherIncome: 0 }));
  });

  test("a deduction does not bring a higher income back into scope", () => {
    assert.equal(calculate({ salary: 5_200_000, otherDeductions: 1_000_000 }).status, "unsupported");
  });

  test("at the ceiling no surcharge can apply: the total income never exceeds Rs 50,00,000 in either regime", () => {
    const r = calculate({ salary: 5_000_000 });
    assert.ok(r.old.totalIncome <= 5_000_000 && r.new.totalIncome <= 5_000_000);
  });
});

describe("break-even", () => {
  test("it is the smallest extra deduction: one rupee less is not enough, and it is found for every golden case", () => {
    for (const salary of [1_500_000, 1_800_000, 2_500_000, 3_000_000, 4_500_000]) {
      const r = calculate({ salary });
      assert.equal(r.breakEven.status, "found");
      const at = calculate({ salary, otherDeductions: r.breakEven.extraRupees });
      assert.ok(at.old.finalTax <= at.new.finalTax, `works at ${salary}`);
      if (r.breakEven.extraRupees > 0) {
        const below = calculate({ salary, otherDeductions: r.breakEven.extraRupees - 1 });
        assert.ok(below.old.finalTax > below.new.finalTax, `one less fails at ${salary}`);
      }
    }
  });

  test("the old regime already wins or ties: no break-even is shown", () => {
    const r = calculate({ salary: 2_000_000, basicPlusDa: 800_000, hraReceived: 400_000, rentPaid: 600_000, highCity: true, section80C: 150_000, ownNps: 50_000, healthSelfFamily: 25_000, homeLoanInterest: 200_000, otherDeductions: 600_000 });
    assert.equal(r.comparison.lower, "old");
    assert.equal(r.breakEven.status, "old-lower-or-equal");
  });

  test("above about Rs 25 lakh both regimes are at 30%, so the break-even is the same amount", () => {
    const at = (s) => calculate({ salary: s }).breakEven.requiredRupees;
    assert.equal(at(2_500_000), at(3_000_000));
    assert.equal(at(3_000_000), at(4_000_000));
    assert.equal(at(4_000_000), at(5_000_000));
  });

  test("the rebate cliff and a zero new-regime tax: the old regime must reach a total income of Rs 5,00,000 or less", () => {
    const r = calculate({ salary: 800_000 });
    assert.equal(r.new.finalTax, 0);
    assert.equal(r.breakEven.status, "found");
    const at = calculate({ salary: 800_000, otherDeductions: r.breakEven.extraRupees });
    assert.equal(at.old.finalTax, 0);
  });

  test("the displayed estimate is rounded to the nearest Rs 1,000", () => {
    const r = calculate({ salary: 1_500_000 });
    assert.equal(r.breakEven.requiredApproxRupees % 1000, 0);
    assert.ok(Math.abs(r.breakEven.requiredApproxRupees - r.breakEven.requiredRupees) <= 500);
  });

  test("it terminates for the largest supported income and for tiny ones", () => {
    for (const salary of [0, 1, 400_000, 5_000_000]) {
      const t = performance.now();
      const r = calculate({ salary });
      assert.ok(performance.now() - t < 200);
      assert.ok(["found", "old-lower-or-equal"].includes(r.breakEven.status));
    }
  });
});

describe("the old regime's tax never rises when a deduction rises", () => {
  test("monotone non-increasing over a grid of extra deductions at several incomes, across the rebate cliff", () => {
    for (const salary of [550_000, 900_000, 1_500_000, 3_000_000, 5_000_000]) {
      let previous = Infinity;
      for (let d = 0; d <= salary; d += 7_500) {
        const tax = calculate({ salary, otherDeductions: d }).old.finalTax;
        assert.ok(tax <= previous, `salary ${salary} deduction ${d}`);
        previous = tax;
      }
    }
  });

  test("the new regime's tax never falls when the salary rises", () => {
    let previous = -1;
    for (let salary = 0; salary <= 5_000_000; salary += 2_500) {
      const tax = calculate({ salary }).new.finalTax;
      assert.ok(tax >= previous, `salary ${salary}`);
      previous = tax;
    }
  });
});

describe("exact money: whole rupees in, integer paise inside, a multiple of ten out", () => {
  test("no result has a floating-point artifact", () => {
    for (let salary = 0; salary <= 4_990_000; salary += 12_345) {
      const r = calculate({ salary, otherIncome: salary % 7_001 });
      for (const side of [r.old, r.new]) {
        for (const key of ["taxBeforeRebate", "rebate", "taxAfterRebate", "cess", "totalBeforeRounding"]) assert.ok(Number.isInteger(side[key]), `${key} ${salary}`);
        assert.equal(side.finalTax % 10, 0);
        assert.equal(side.totalIncome % 10, 0);
      }
    }
  });
});

describe("validation", () => {
  test("a negative, fractional, non-numeric or huge value is refused with a message for that field", () => {
    for (const bad of [-1, 1.5, "100", NaN, Infinity, null]) {
      const r = calculate({ salary: bad });
      assert.equal(r.status, "invalid", String(bad));
      assert.match(r.errors.salary, /whole number of rupees/);
    }
    assert.equal(calculate({ salary: FIELD_MAX + 1 }).status, "invalid");
    assert.equal(calculate({ salary: 1_000_000, section80C: -5 }).errors.section80C.length > 0, true);
  });

  test("basic + DA and HRA must fit inside the salary, and are needed where a share of them is used", () => {
    assert.match(calculate({ salary: 500_000, basicPlusDa: 600_000 }).errors.basicPlusDa, /cannot be more than your annual salary/);
    assert.match(calculate({ salary: 500_000, basicPlusDa: 300_000, hraReceived: 300_000 }).errors.hraReceived, /together cannot be more/);
    assert.match(calculate({ salary: 1_000_000, hraReceived: 100_000 }).errors.basicPlusDa, /Enter your basic salary plus DA/);
    assert.match(calculate({ salary: 1_000_000, employerNps: 50_000 }).errors.basicPlusDa, /employer NPS limit/);
    assert.match(calculate({ salary: 1_000_000, hraMode: "manual", hraManual: 2_000_000 }).errors.hraManual, /cannot be more than your annual salary/);
    assert.equal(calculate({ salary: 1_000_000, hraMode: "manual", hraManual: 100_000 }).status, "ok");
  });

  test("validateInput defaults missing fields and reports ok", () => {
    const v = validateInput({ salary: 100 });
    assert.equal(v.ok, true);
    assert.equal(v.input.section80C, 0);
    assert.equal(v.input.hraMode, "calculate");
  });

  test("the empty input is a valid, zero result", () => {
    const r = calculate({});
    assert.equal(r.status, "ok");
    assert.equal(r.old.finalTax, 0);
    assert.equal(r.new.finalTax, 0);
    assert.equal(r.comparison.lower, "equal");
    assert.equal(r.effective.newPermille, null);
  });
});

describe("the tax-year configuration", () => {
  test("it is the 2026-27 tax year, immutable, and the one the page uses", () => {
    assert.equal(ACTIVE_TAX_YEAR, TAX_YEAR_2026_27);
    assert.equal(TAX_YEAR_2026_27.taxYear, "2026-27");
    assert.equal(TAX_YEAR_2026_27.financialYear, "FY 2026-27");
    assert.ok(Object.isFrozen(TAX_YEAR_2026_27) && Object.isFrozen(TAX_YEAR_2026_27.slabs.new) && Object.isFrozen(TAX_YEAR_2026_27.slabs.new[0]) && Object.isFrozen(TAX_YEAR_2026_27.caps.employerNpsPercent));
    assert.throws(() => { "use strict"; TAX_YEAR_2026_27.cessPercent = 5; });
  });

  test("every value is the one read from the law (a change here is a deliberate, verified edit)", () => {
    const c = TAX_YEAR_2026_27;
    assert.deepEqual(c.slabs.old, [{ upTo: 250000, ratePercent: 0 }, { upTo: 500000, ratePercent: 5 }, { upTo: 1000000, ratePercent: 20 }, { upTo: null, ratePercent: 30 }]);
    assert.deepEqual(c.slabs.new.map((s) => [s.upTo, s.ratePercent]), [[400000, 0], [800000, 5], [1200000, 10], [1600000, 15], [2000000, 20], [2400000, 25], [null, 30]]);
    assert.deepEqual(c.standardDeduction, { new: 75000, old: 50000 });
    assert.deepEqual(c.rebate, { old: { maxTotalIncome: 500000, maxRebate: 12500 }, new: { maxTotalIncome: 1200000, maxRebate: 60000 } });
    assert.equal(c.cessPercent, 4);
    assert.equal(c.roundingMultiple, 10);
    assert.equal(c.supportedIncomeCeiling, 5_000_000);
    assert.equal(c.caps.section80C, 150000);
    assert.equal(c.caps.ownNps, 50000);
    assert.deepEqual([c.caps.healthSelfFamily, c.caps.healthParentsUnder60, c.caps.healthParentsSenior], [25000, 25000, 50000]);
    assert.deepEqual([c.caps.homeLoanInterestStandard, c.caps.homeLoanInterestOther], [200000, 30000]);
    assert.deepEqual(c.caps.employerNpsPercent, { oldRegime: 10, oldRegimeGovernmentEmployer: 14, newRegime: 14 });
    assert.deepEqual(c.hra.highCities, ["Mumbai", "Kolkata", "Delhi", "Chennai", "Hyderabad", "Pune", "Ahmedabad", "Bengaluru"]);
    assert.deepEqual([c.hra.rentExcessOverPercentOfSalary, c.hra.highCityPercentOfSalary, c.hra.otherPercentOfSalary], [10, 50, 40]);
  });

  test("it names its sources, each with an https URL", () => {
    assert.ok(TAX_YEAR_2026_27.sources.length >= 4);
    for (const s of TAX_YEAR_2026_27.sources) {
      assert.ok(s.topic && s.title && s.publisher);
      assert.match(s.url, /^https:\/\/(egazette\.gov\.in|www\.incometax\.gov\.in|www\.pib\.gov\.in)\//);
    }
    assert.ok(Date.parse(TAX_YEAR_2026_27.verifiedOn) > 0);
  });

  test("the slabs are contiguous and end with an open band", () => {
    for (const regime of ["old", "new"]) {
      const slabs = TAX_YEAR_2026_27.slabs[regime];
      assert.equal(slabs.at(-1).upTo, null);
      for (let i = 1; i < slabs.length - 1; i++) assert.ok(slabs[i].upTo > slabs[i - 1].upTo);
      for (let i = 1; i < slabs.length; i++) assert.ok(slabs[i].ratePercent > slabs[i - 1].ratePercent);
    }
  });

  test("STALENESS TRIPWIRE: this fails 90 days after the tax year ends, to force the annual update (never carry the numbers forward)", () => {
    const limit = Date.parse(TAX_YEAR_2026_27.validThrough) + 90 * 86_400_000;
    assert.ok(
      Date.now() <= limit,
      `The ${TAX_YEAR_2026_27.label} rules are past their review date. Verify the law for the next tax year, add a new configuration, and follow the annual-update checklist in docs/tool-packs/17-income-tax-regime-comparison.md.`,
    );
  });
});
